CREATE OR REPLACE FUNCTION fixeo_private._write_enterprise_audit_event(p_enterprise_id uuid, p_event_type text, p_target_type text, p_target_id uuid, p_before_state jsonb DEFAULT NULL::jsonb, p_after_state jsonb DEFAULT NULL::jsonb, p_metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_event_id uuid;
  v_actor_user_id uuid;
  v_event_type text;
  v_target_type text;
  v_metadata jsonb;
BEGIN
  IF p_enterprise_id IS NULL THEN
    RAISE EXCEPTION 'enterprise_id_required';
  END IF;

  v_actor_user_id := auth.uid();
  IF v_actor_user_id IS NULL THEN
    RAISE EXCEPTION 'actor_user_id_required';
  END IF;

  v_event_type := pg_catalog.btrim(p_event_type);
  IF v_event_type IS NULL OR pg_catalog.char_length(v_event_type) < 1 THEN
    RAISE EXCEPTION 'event_type_required';
  END IF;

  v_target_type := pg_catalog.btrim(p_target_type);
  IF v_target_type IS NULL OR pg_catalog.char_length(v_target_type) < 1 THEN
    RAISE EXCEPTION 'target_type_required';
  END IF;

  IF p_before_state IS NOT NULL
     AND pg_catalog.jsonb_typeof(p_before_state) <> 'object'
  THEN
    RAISE EXCEPTION 'before_state_must_be_object';
  END IF;

  IF p_after_state IS NOT NULL
     AND pg_catalog.jsonb_typeof(p_after_state) <> 'object'
  THEN
    RAISE EXCEPTION 'after_state_must_be_object';
  END IF;

  v_metadata := COALESCE(p_metadata, '{}'::jsonb);

  IF pg_catalog.jsonb_typeof(v_metadata) <> 'object' THEN
    RAISE EXCEPTION 'metadata_must_be_object';
  END IF;

  INSERT INTO public.enterprise_audit_events (
    enterprise_id,
    actor_user_id,
    event_type,
    target_type,
    target_id,
    before_state,
    after_state,
    metadata
  )
  VALUES (
    p_enterprise_id,
    v_actor_user_id,
    v_event_type,
    v_target_type,
    p_target_id,
    p_before_state,
    p_after_state,
    v_metadata
  )
  RETURNING id INTO v_event_id;

  RETURN v_event_id;
END;
$function$

CREATE OR REPLACE FUNCTION fixeo_private.enforce_profile_canonical_role_p0()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  canonical_role text;
BEGIN
  SELECT u.role INTO canonical_role FROM public.users u WHERE u.id = NEW.id;
  IF NOT FOUND OR canonical_role IS NULL
     OR canonical_role NOT IN ('admin','artisan','client') THEN
    RAISE EXCEPTION 'canonical_identity_missing_or_invalid' USING ERRCODE='23514';
  END IF;
  NEW.role := canonical_role;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION fixeo_private._fixeo_is_admin()
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_caller_id uuid;
  v_result    boolean;
BEGIN
  v_caller_id := auth.uid();
  IF v_caller_id IS NULL THEN
    RETURN false;
  END IF;

  SELECT EXISTS (
    SELECT 1
    FROM   public.users u
    WHERE  u.id   = v_caller_id
      AND  u.role = 'admin'
  ) INTO v_result;

  RETURN COALESCE(v_result, false);
END;
$function$

CREATE OR REPLACE FUNCTION fixeo_private._fixeo_is_enterprise_member(p_enterprise_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_caller_id uuid;
  v_result    boolean;
BEGIN
  v_caller_id := auth.uid();
  IF v_caller_id IS NULL OR p_enterprise_id IS NULL THEN
    RETURN false;
  END IF;

  SELECT EXISTS (
    SELECT 1
    FROM   public.enterprise_members em
    WHERE  em.enterprise_id = p_enterprise_id
      AND  em.user_id       = v_caller_id
      AND  em.status        = 'active'
  ) INTO v_result;

  RETURN COALESCE(v_result, false);
END;
$function$

CREATE OR REPLACE FUNCTION fixeo_private._fixeo_is_enterprise_manager(p_enterprise_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_caller_id uuid;
  v_result    boolean;
BEGIN
  v_caller_id := auth.uid();
  IF v_caller_id IS NULL OR p_enterprise_id IS NULL THEN
    RETURN false;
  END IF;

  SELECT EXISTS (
    SELECT 1
    FROM   public.enterprise_members em
    WHERE  em.enterprise_id = p_enterprise_id
      AND  em.user_id       = v_caller_id
      AND  em.role          IN ('owner', 'admin')
      AND  em.status        = 'active'
  ) INTO v_result;

  RETURN COALESCE(v_result, false);
END;
$function$
